/* Rentcam CMS v6 promo schedule extension */
(function(){
 if(!location.pathname.startsWith('/cms'))return;
 let productId=null,bannerIndex=null,pendingProduct=null,pendingBanner=null;
 const publishing=()=>window.RentcamCmsPublishing;
 const cfg=()=>publishing().get();
 const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
 function meta(id){return publishing().product(id,false)||{}}
 function ensure(id){return publishing().product(id,true)}
 function save(){return publishing().save().catch(e=>console.error('Gagal menyimpan promo CMS',e))}
 function style(){if(document.getElementById('v6promo-style'))return;const s=document.createElement('style');s.id='v6promo-style';s.textContent=`.v6-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.v6-grid label{display:block;font-size:13px;font-weight:800;margin-bottom:6px;color:#555}.v6-grid input{width:100%;height:44px;border:1px solid #dfe2e6;border-radius:9px;padding:0 11px;font:inherit;font-size:14px}.v6-grid .full{grid-column:1/-1}.v6-note{font-size:11px;color:#80848a;margin-top:8px;line-height:1.5}.v6-rowbtns{display:flex;gap:7px;flex-wrap:wrap}.v6-btn{height:38px;border:1px solid #dfe1e5;border-radius:9px;background:#fff;padding:0 11px;font-weight:800;font-size:12px;cursor:pointer}.v6-btn.warn{background:#fff9e8;color:#8a6500}.v6-btn.danger{background:#fff3f3;color:#b52e2e;border-color:#ffd5d5}@media(max-width:700px){.v6-grid{grid-template-columns:1fr}}`;document.head.appendChild(s)}
 function productSection(id){const x=meta(id);return `<section class="v5-section" id="v6ProductPromo"><h3>Label, Jadwal & Diskon</h3><div class="v6-grid"><div><label>Label Produk</label><input data-v6p="labelText" value="${esc(x.labelText||'')}" placeholder="BARU / PROMO / BEST SELLER"></div><div><label>Tanggal Mulai Tampil Produk</label><input data-v6p="publishDate" type="date" value="${esc(x.publishDate||'')}"></div><div><label>Tanggal Berhenti Tampil Produk</label><input data-v6p="unpublishDate" type="date" value="${esc(x.unpublishDate||'')}"></div><div><label>Tanggal Label Mulai</label><input data-v6p="labelStart" type="date" value="${esc(x.labelStart||'')}"></div><div><label>Tanggal Label Hilang</label><input data-v6p="labelEnd" type="date" value="${esc(x.labelEnd||'')}"></div><div><label>Diskon (%)</label><input data-v6p="discountPercent" type="number" min="0" max="100" value="${esc(x.discountPercent||0)}"></div><div><label>Tanggal Mulai Diskon</label><input data-v6p="discountStart" type="date" value="${esc(x.discountStart||'')}"></div><div><label>Tanggal Selesai Diskon</label><input data-v6p="discountEnd" type="date" value="${esc(x.discountEnd||'')}"></div><div class="full"><label>Nama Promo</label><input data-v6p="discountLabel" value="${esc(x.discountLabel||'')}" placeholder="Contoh: Promo September"></div></div><div class="v6-note">Tanggal memakai kalender. Setelah tanggal selesai, label/diskon/produk otomatis berhenti tampil.</div></section>`}
 function bannerSection(){const x=bannerIndex==null?{}:(cfg().banners||[])[bannerIndex]||{};return `<section class="v5-section" id="v6BannerPromo"><h3>Jadwal Banner Promo</h3><div class="v6-grid"><div><label>Label Promo</label><input data-v6b="promoLabel" value="${esc(x.promoLabel||'')}"></div><div><label>Diskon (%)</label><input data-v6b="discountPercent" type="number" min="0" max="100" value="${esc(x.discountPercent||0)}"></div><div><label>Tanggal Mulai Banner</label><input data-v6b="startDate" type="date" value="${esc(x.startDate||'')}"></div><div><label>Tanggal Selesai Banner</label><input data-v6b="endDate" type="date" value="${esc(x.endDate||'')}"></div><div class="full"><label><input data-v6b="active" type="checkbox" ${x.active===false?'':'checked'} style="width:auto;height:auto"> Banner Aktif</label></div></div><div class="v6-note">Banner otomatis tidak tampil jika belum mulai atau masa promonya sudah selesai.</div></section>`}
 function enhanceModal(){const m=document.querySelector('.v5-modal');if(!m)return;const id=m.querySelector('[data-mfield="id"]')?.value||productId;const head=m.querySelector('.v5-modalhead h3')?.textContent||'';const body=m.querySelector('.v5-modalbody');if(id&&body&&!m.querySelector('#v6ProductPromo'))body.insertAdjacentHTML('beforeend',productSection(id));if(/banner/i.test(head)&&body&&!m.querySelector('#v6BannerPromo'))body.insertAdjacentHTML('beforeend',bannerSection())}
 function enhanceProductRows(){document.querySelectorAll('[data-action="edit-product"][data-id]').forEach(edit=>{const td=edit.closest('td');if(!td||td.querySelector('[data-v6-toggle-product]'))return;const id=edit.dataset.id,wrap=document.createElement('div');wrap.className='v6-rowbtns';edit.replaceWith(wrap);wrap.appendChild(edit);const t=document.createElement('button');t.className='v6-btn warn';t.dataset.v6ToggleProduct=id;t.textContent=meta(id).active===false?'Aktifkan':'Nonaktif';const d=document.createElement('button');d.className='v6-btn danger';d.dataset.v6DeleteProduct=id;d.textContent='Hapus';wrap.append(t,d)})}
 function enhanceBannerRows(){document.querySelectorAll('[data-action="edit-banner"][data-index]').forEach(edit=>{const host=edit.parentElement;if(!host||host.querySelector('[data-v6-toggle-banner]'))return;const i=edit.dataset.index,x=(cfg().banners||[])[+i]||{};const t=document.createElement('button');t.className='v6-btn warn';t.dataset.v6ToggleBanner=i;t.textContent=x.active===false?'Aktifkan':'Nonaktif';host.appendChild(t)})}
 document.addEventListener('click',e=>{
   const ep=e.target.closest('[data-action="edit-product"]');if(ep)productId=ep.dataset.id;
   if(e.target.closest('[data-action="add-product"]'))productId=null;
   const eb=e.target.closest('[data-action="edit-banner"]');if(eb)bannerIndex=Number(eb.dataset.index);
   if(e.target.closest('[data-action="add-banner"]'))bannerIndex=null;
   if(e.target.closest('[data-action="save-modal"]')){
     const m=document.querySelector('.v5-modal');if(m?.querySelector('#v6ProductPromo')){pendingProduct={id:m.querySelector('[data-mfield="id"]')?.value||productId||''};m.querySelectorAll('[data-v6p]').forEach(x=>pendingProduct[x.dataset.v6p]=x.type==='number'?Number(x.value)||0:x.value)}
     if(m?.querySelector('#v6BannerPromo')){pendingBanner={};m.querySelectorAll('[data-v6b]').forEach(x=>pendingBanner[x.dataset.v6b]=x.type==='checkbox'?x.checked:x.type==='number'?Number(x.value)||0:x.value)}
     setTimeout(()=>{if(pendingProduct?.id){const id=pendingProduct.id,patch={...pendingProduct};delete patch.id;publishing().patchProductSchedule(id,patch);pendingProduct=null;save()}if(pendingBanner){const a=cfg().banners||[];let i=bannerIndex;if(i==null||!a[i])i=a.length-1;if(i>=0)publishing().patchBannerSchedule(i,pendingBanner);pendingBanner=null;save()}},80)
   }
 },true);
 document.addEventListener('click',e=>{
   const t=e.target.closest('[data-v6-toggle-product]');if(t){publishing().toggleProduct(t.dataset.v6ToggleProduct);save();setTimeout(()=>location.reload(),250);return}
   const d=e.target.closest('[data-v6-delete-product]');if(d){publishing().deleteProduct(d.dataset.v6DeleteProduct);save();setTimeout(()=>location.reload(),250);return}
   const b=e.target.closest('[data-v6-toggle-banner]');if(b){if(publishing().toggleCollection('banners',+b.dataset.v6ToggleBanner)){save();setTimeout(()=>location.reload(),250)}}
 });
 const mo=new MutationObserver(()=>{style();enhanceModal();enhanceProductRows();enhanceBannerRows()});mo.observe(document.documentElement,{subtree:true,childList:true});style();setTimeout(()=>{enhanceModal();enhanceProductRows();enhanceBannerRows()},500);
})();